/**
 * @veritasacta/artifacts — Signed Artifact Envelope
 *
 * Canonical serialization, Ed25519 signing, and verification
 * for typed JSON payloads (receipts, anchors, resolutions, etc.)
 *
 * Supports both v1 (flat envelope) and v2 (structured envelope with kid, issuer, payload).
 * Both ScopeBlind and Veritas Acta use this shared primitive.
 *
 * @license MIT
 */

import { ed25519 } from '@noble/curves/ed25519';
import { sha256 } from '@noble/hashes/sha256';
import { bytesToHex, hexToBytes, utf8ToBytes } from '@noble/hashes/utils';

// ── Canonical Serialization ─────────────────────────────────────

/**
 * Produce a deterministic JSON string from an object.
 * Keys are sorted lexicographically at every level (JCS-style).
 * ASCII-only keys enforced: throws if any key contains non-ASCII characters.
 *
 * @param {Record<string, unknown>} obj
 * @returns {string}
 */
export function canonicalize(obj) {
  return JSON.stringify(obj, (_key, value) => {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const sorted = {};
      for (const k of Object.keys(value).sort()) {
        // Enforce ASCII-only keys
        if (!/^[\x20-\x7E]*$/.test(k)) {
          throw new Error(`Non-ASCII key "${k}" in artifact payload. Only ASCII keys are permitted.`);
        }
        sorted[k] = value[k];
      }
      return sorted;
    }
    return value;
  });
}

/**
 * SHA-256 hash of the canonical form of an object.
 * Returns lowercase hex.
 *
 * @param {Record<string, unknown>} obj
 * @returns {string}
 */
export function canonicalHash(obj) {
  return bytesToHex(sha256(utf8ToBytes(canonicalize(obj))));
}

// ── v1 Signing (backwards compatible) ───────────────────────────

/**
 * Sign a v1 artifact payload with Ed25519.
 * v1 artifacts have a flat structure: all payload fields at top level.
 *
 * @param {Record<string, unknown>} payload - Must include `v`, `type`, `timestamp`.
 * @param {string} privateKeyHex - 64-char hex-encoded Ed25519 private key.
 * @returns {{ artifact: Record<string, unknown>, signature: string, hash: string }}
 */
export function signArtifact(payload, privateKeyHex) {
  if (!payload.v || !payload.type || !payload.timestamp) {
    throw new Error('Artifact must include v, type, and timestamp fields');
  }

  const message = utf8ToBytes(canonicalize(payload));
  const signature = bytesToHex(ed25519.sign(message, hexToBytes(privateKeyHex)));
  const hash = bytesToHex(sha256(message));

  return {
    artifact: { ...payload, signature },
    signature,
    hash,
  };
}

// ── v2 Signing (new structured envelope) ────────────────────────

/**
 * Create and sign a v2 artifact with structured envelope.
 *
 * v2 artifacts separate envelope metadata from type-specific payload:
 * { v: 2, type, algorithm, kid, issuer, issued_at, payload: {...}, signature }
 *
 * @param {string} type - Artifact type (e.g., "decision_receipt", "trust_ticket")
 * @param {Record<string, unknown>} payload - Type-specific payload fields
 * @param {string} privateKeyHex - 64-char hex Ed25519 private key
 * @param {{ kid: string, issuer: string, issued_at?: string }} meta - Envelope metadata
 * @returns {{ artifact: Record<string, unknown>, signature: string, hash: string }}
 */
export function createSignedArtifact(type, payload, privateKeyHex, meta) {
  if (!type) throw new Error('Artifact type is required');
  if (!meta?.kid) throw new Error('kid is required for v2 artifacts');
  if (!meta?.issuer) throw new Error('issuer is required for v2 artifacts');

  const envelope = {
    v: 2,
    type,
    algorithm: 'ed25519',
    kid: meta.kid,
    issuer: meta.issuer,
    issued_at: meta.issued_at || new Date().toISOString(),
    payload,
  };

  const message = utf8ToBytes(canonicalize(envelope));
  const signature = bytesToHex(ed25519.sign(message, hexToBytes(privateKeyHex)));
  const hash = bytesToHex(sha256(message));

  return {
    artifact: { ...envelope, signature },
    signature,
    hash,
  };
}

// ── Unified Verification ────────────────────────────────────────

/**
 * Verify an artifact's Ed25519 signature.
 * Works for both v1 (flat) and v2 (structured) artifacts.
 *
 * @param {Record<string, unknown>} artifact - Signed artifact (with `signature` field).
 * @param {string} publicKeyHex - 64-char hex-encoded Ed25519 public key.
 * @returns {{ valid: boolean, hash?: string, error?: string, version?: number }}
 */
export function verifyArtifact(artifact, publicKeyHex) {
  try {
    if (!artifact.signature) {
      return { valid: false, error: 'missing_signature' };
    }

    // Strip signature to reconstruct the signed message
    const { signature, ...payload } = artifact;
    const message = utf8ToBytes(canonicalize(payload));
    const hash = bytesToHex(sha256(message));

    const valid = ed25519.verify(
      hexToBytes(signature),
      message,
      hexToBytes(publicKeyHex),
    );

    return valid
      ? { valid: true, hash, version: artifact.v || 1 }
      : { valid: false, hash, error: 'invalid_signature', version: artifact.v || 1 };
  } catch (err) {
    return { valid: false, error: 'verification_error' };
  }
}

// ── JWK Thumbprint (RFC 7638) ───────────────────────────────────

/**
 * Compute a JWK thumbprint (RFC 7638) as the key identifier (kid).
 * For Ed25519: SHA-256 of the canonical JWK members {"crv","kty","x"}.
 *
 * @param {string} publicKeyHex - 64-char hex-encoded Ed25519 public key
 * @returns {string} Base64url-encoded SHA-256 thumbprint
 */
export function computeKid(publicKeyHex) {
  const pubBytes = hexToBytes(publicKeyHex);
  const x = bytesToBase64url(pubBytes);

  // RFC 7638: lexicographically ordered required members for OKP
  const thumbprintInput = `{"crv":"Ed25519","kty":"OKP","x":"${x}"}`;
  const hash = sha256(utf8ToBytes(thumbprintInput));
  return bytesToBase64url(hash);
}

// ── Holder Binding Commitment ───────────────────────────────────

/**
 * Compute a holder-binding commitment (HBC).
 * HBC = H("DS_holder_bind" || key_material || nonce)
 *
 * The client chooses the nonce. Failure to reproduce the commitment
 * is self-punishing (the holder can't prove continuity).
 *
 * @param {Uint8Array} keyMaterial - The holder's key material
 * @param {Uint8Array} nonce - Client-chosen nonce
 * @returns {string} Hex-encoded SHA-256 commitment
 */
export function computeHolderBinding(keyMaterial, nonce) {
  const label = utf8ToBytes('DS_holder_bind');
  const combined = new Uint8Array(label.length + keyMaterial.length + nonce.length);
  combined.set(label, 0);
  combined.set(keyMaterial, label.length);
  combined.set(nonce, label.length + keyMaterial.length);
  return bytesToHex(sha256(combined));
}

// ── Public Key Utilities ────────────────────────────────────────

/**
 * Convert an Ed25519 public key to JWK format (RFC 8037).
 *
 * @param {string} publicKeyHex - Hex-encoded Ed25519 public key
 * @param {string} [kid] - Key ID (defaults to computed JWK thumbprint)
 * @returns {{ kty: string, crv: string, kid: string, x: string, use: string }}
 */
export function publicKeyToJWK(publicKeyHex, kid) {
  const pubBytes = hexToBytes(publicKeyHex);
  const x = bytesToBase64url(pubBytes);
  return {
    kty: 'OKP',
    crv: 'Ed25519',
    kid: kid || computeKid(publicKeyHex),
    x,
    use: 'sig',
  };
}

// ── Payload Validators ──────────────────────────────────────────

/**
 * Registered v2 artifact types and their required payload fields.
 */
const ARTIFACT_SCHEMAS = {
  decision_receipt: {
    required: ['decision', 'policy_digest', 'scope'],
    optional: [
      'disclosure_mode', 'identity_class', 'identity_repr',
      'holder_binding', 'epoch', 'timestamp', 'annex_hash',
      'chain_prev', 'tool', 'reason_code', 'rate_limit_remaining',
      'credential_ref', 'tier', 'mode', 'request_id',
    ],
  },
  gateway_restraint: {
    required: ['tool', 'decision', 'reason_code', 'policy_digest'],
    optional: [
      'agent_id', 'tier', 'request_scope',
      'rate_limit_state', 'mode',
    ],
  },
  trust_ticket: {
    required: ['tier', 'scope', 'expires_at'],
    optional: [
      'agent_id', 'manifest_hash', 'evidence_summary',
    ],
  },
  audit_anchor: {
    required: ['merkle_root', 'chain_heads'],
    optional: [
      'topic_count', 'public_key', 'charter_hash',
      'protocol_spec_hash', 'protocol_version', 'policy_hash',
      'receipt_count', 'time_range',
    ],
  },
  agent_manifest: {
    required: ['agent_id', 'public_key', 'version'],
    optional: [
      'display_name', 'description', 'domain_lanes',
      'model_family_hash', 'memory_mode', 'prompt_hash',
      'tool_classes', 'config_hashes', 'previous_version',
      'evidence_pointers', 'auth_key_bindings',
    ],
  },
};

/**
 * Validate a v2 artifact's payload against its type schema.
 *
 * @param {string} type - Artifact type
 * @param {Record<string, unknown>} payload - Payload to validate
 * @returns {{ valid: boolean, errors: string[] }}
 */
export function validatePayload(type, payload) {
  const errors = [];
  const schema = ARTIFACT_SCHEMAS[type];

  if (!schema) {
    return { valid: true, errors: [] }; // Unknown types pass through (forward compat)
  }

  if (!payload || typeof payload !== 'object') {
    return { valid: false, errors: ['payload must be an object'] };
  }

  for (const field of schema.required) {
    if (payload[field] === undefined || payload[field] === null) {
      errors.push(`missing required field: ${field}`);
    }
  }

  return { valid: errors.length === 0, errors };
}

// ── Trust Tier Constants ────────────────────────────────────────

/**
 * Trust tiers in ascending order of privilege.
 * Tiers are a closed, ordered set for policy evaluation.
 */
export const TRUST_TIERS = ['unknown', 'signed-known', 'evidenced', 'privileged'];

/**
 * Compare two trust tiers.
 * @param {string} a
 * @param {string} b
 * @returns {number} negative if a < b, 0 if equal, positive if a > b
 */
export function compareTiers(a, b) {
  return TRUST_TIERS.indexOf(a) - TRUST_TIERS.indexOf(b);
}

/**
 * Check if a tier meets a minimum tier requirement.
 * @param {string} actual - The agent's current tier
 * @param {string} required - The minimum tier required
 * @returns {boolean}
 */
export function meetsMinTier(actual, required) {
  return compareTiers(actual, required) >= 0;
}

// ── Keypair Utilities ───────────────────────────────────────────

/**
 * Generate a new Ed25519 keypair with computed kid.
 * @returns {{ privateKey: string, publicKey: string, kid: string }}
 */
export function generateKeypair() {
  const privateKey = ed25519.utils.randomPrivateKey();
  const publicKey = ed25519.getPublicKey(privateKey);
  const pubHex = bytesToHex(publicKey);
  return {
    privateKey: bytesToHex(privateKey),
    publicKey: pubHex,
    kid: computeKid(pubHex),
  };
}

/**
 * Derive the public key from a private key.
 * @param {string} privateKeyHex
 * @returns {string}
 */
export function getPublicKey(privateKeyHex) {
  return bytesToHex(ed25519.getPublicKey(hexToBytes(privateKeyHex)));
}

// ── Base64url Utilities ─────────────────────────────────────────

/**
 * Encode bytes as base64url (no padding).
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function bytesToBase64url(bytes) {
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/**
 * Decode base64url string to bytes.
 * @param {string} b64url
 * @returns {Uint8Array}
 */
export function base64urlToBytes(b64url) {
  let b64 = b64url.replace(/-/g, '+').replace(/_/g, '/');
  while (b64.length % 4) b64 += '=';
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

// ── Re-exports for convenience ──────────────────────────────────

export { bytesToHex, hexToBytes, utf8ToBytes } from '@noble/hashes/utils';
export { sha256 } from '@noble/hashes/sha256';
